// ============================================================
// LAS CUATRO RESTRICCIONES
// El nivel dice SI puede. Esto dice HASTA DONDE.
// ============================================================
const i = $('Intencion de prueba').first().json;
const enviosHoy = $input.all().map(x => x.json);   // filas de contador_envios
const fallos = [];

// 1 · DE ALCANCE ------------------------------------------------
const MAX_DESTINOS = 60;
if (Number(i.destinatarios || 0) > MAX_DESTINOS) {
  fallos.push('ALCANCE: ' + i.destinatarios + ' destinatarios (maximo ' + MAX_DESTINOS + ').');
}
const CENTROS_OK = ['Las Acacias'];
if (i.centro && !CENTROS_OK.includes(i.centro)) {
  fallos.push('ALCANCE: el centro "' + i.centro + '" no esta permitido.');
}

// 2 · DE FRECUENCIA ---------------------------------------------
const MAX_POR_SOCIA_DIA = 1;
const yaEnviados = enviosHoy.filter(f => f.socia === i.socia && f.fecha === $now.toFormat('yyyy-LL-dd')).length;
if (i.socia && yaEnviados >= MAX_POR_SOCIA_DIA) {
  fallos.push('FRECUENCIA: ya se ha escrito hoy a ' + i.socia + '.');
}
const MAX_MASIVOS_SEMANA = 3;
const masivosSemana = enviosHoy.filter(f => Number(f.destinatarios || 0) > 10).length;
if (Number(i.destinatarios || 0) > 10 && masivosSemana >= MAX_MASIVOS_SEMANA) {
  fallos.push('FRECUENCIA: ya van ' + masivosSemana + ' avisos masivos esta semana.');
}

// 3 · DE CONTENIDO ----------------------------------------------
const texto = (i.texto || '').toLowerCase();
const PROHIBIDO = ['dosis', 'medicamento', 'diagnostico', 'tension arterial', 'receta'];
const encontrado = PROHIBIDO.filter(p => texto.includes(p));
if (encontrado.length) {
  fallos.push('CONTENIDO: el texto menciona ' + encontrado.join(', ') + ' (consejo medico).');
}
if (Number(i.destinatarios || 0) > 1 && /hipertens|cardiopat|diabet|artrosis/.test(texto)) {
  fallos.push('CONTENIDO: no se pueden nombrar patologias en un correo grupal (RGPD).');
}
if (i.accion === 'responder_a_una_socia' && !i.fuente) {
  fallos.push('CONTENIDO: falta la fuente. Toda respuesta con datos del RAG debe citarla.');
}

// 4 · DE MOMENTO ------------------------------------------------
const hora = Number($now.setZone('Europe/Madrid').toFormat('HH'));
if (hora >= 22 || hora < 8) {
  fallos.push('MOMENTO: son las ' + hora + ':00. Nada se envia entre las 22:00 y las 8:00.');
}
if (i.accion === 'cancelar_clase' && Number(i.antelacion_h || 0) < 24) {
  fallos.push('MOMENTO: cancelar con ' + i.antelacion_h + ' h de antelacion (minimo 24 h).');
}

return [{ json: {
  ...i,
  permitido: fallos.length === 0,
  fallos,
  resumen: fallos.length === 0
    ? 'Pasa las cuatro restricciones.'
    : fallos.length + ' restriccion(es) incumplida(s).'
}}];
